#!/usr/bin/env python3
"""Writes the 30-day queue: episodes/epNNN-*.json (with b-roll prompts) and queue/plan.json.

Every line a video says must be a line the live site says (facts[] keeps the quote and the page). The daily job
re-reads those pages on the publish day and skips an episode whose quote is gone, so a script written today
cannot go out after the site changed underneath it.
Run once: python3 tools/make_queue.py  (re-running rewrites the files but keeps clip status in queue/plan.json).
"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
