PALS = ["candy", "sunrise", "forest", "ember"]          # aurora (ep005) and ocean (ep006 test) failed the hue-spread check: too many blues
STYLE = " Cinematic, slow camera, night-time mood, rich colour, shallow depth of field. No text, no letters, no logos, no screens with readable words, no faces."


def hook(a, b, s): return {"type": "hook", "lines": [a, b], "sentences": [s]}
def nox(s): return {"type": "bubble", "big": "Hi, I'm Nox.", "small": "Your night-shift video editor.", "lock": True, "sentences": ["Hi, I'm Nox.", s]}
def steps(topic, items, sents): return {"type": "steps", "topic": topic, "items": [{"label": f"{i+1}  {l}", "sub": s} for i, (l, s) in enumerate(items)], "sentences": sents}
def chips(header, items, sents): return {"type": "chips", "header": header, "items": [{"title": t, "sub": s} for t, s in items], "sentences": sents}
def approve(s1="Finished videos upload to YouTube as private.", s2="You watch it first.", s3="Nothing goes public until you say so."):
    return {"type": "approve", "headline": "Nothing airs until you say so.", "button": "Approve", "sign": "You decide  ·  always", "sentences": [s1, s2, s3]}
def cta(tag, s="Start free with one hundred credits at nightshift-ai dot studio."):
    return {"type": "cta", "pills": ["100 free credits", "No card needed"], "tagline": tag, "sentences": [s]}

PRIVATE = [(HOME, "Finished videos upload to YouTube as private"), (HOME, "Nothing goes public until you say so"),
           (HOME, "100 free credits, once, when you sign up. No card.")]

