assert len(EPS) == 30, len(EPS)


# Second hook line per episode: the hook alone was ~3 s, and every episode came out ~28 s against a 40-60 s target.
H2 = {"topic": "Script, voice, visuals and captions, from one line.", "threesteps": "Two are Nightshift's. The last one is yours.",
      "freestart": "Here is what that gets you.", "images": "The Studio makes it, priced on the button.", "clips": "Here is how the Studio does it.",
      "voice": "The Studio voices it, priced on the button.", "styles": "And a style adds no credits.", "characters": "Keep it under an at-name.",
      "channelself": "Every channel keeps its own settings.", "noswap": "If the chosen voice is unavailable, the run stops.",
      "confirmed": "It will not run a channel YouTube has not confirmed.", "publishcheck": "Here is the publish check.",
      "autopublishoff": "Auto-publish is off unless you turn it on.", "languages": "The app speaks all three.",
      "analytics": "Read with the access you granted.", "googledata": "Here is exactly what it is used for.", "history": "Every hold, charge and return.",
      "spendorder": "Here is the order.", "cancel": "Here is how it works.", "drafts": "The editor kept a draft.",
      "export": "Up to thirty minutes, for zero credits.", "tryexample": "Type any topic on the site.", "thumbnail": "Every plan comes with a thumbnail brief.",
      "multichannel": "Keep the last word on each.", "pricetwice": "And if it changes, you are asked again.",
      "developers": "Start videos from your own systems.", "crossfade": "Two editor tools, both free.", "parallel": "It depends on your plan.",
      "pressed": "And the press shows the price.", "planmonth": "Here is the math."}
PRICEY = {"freestart", "history", "spendorder", "cancel", "pricetwice", "parallel", "planmonth", "pressed"}
def pad(slug, scenes):
    scenes[0]["sentences"].append(H2[slug])
    scenes[1]["sentences"].append("I work the night shift, so your channel does not have to.")
    extra = (chips("ALSO IN THE STUDIO", [("One piece at a time", "Picture, clip or voice"), ("Editor", "No credits")],
                   ["Need just one piece? The Studio makes it.", "And the editor uses no credits."]) if slug in PRICEY else
             chips("BEFORE ANYTHING STARTS", [("Price first", "On the button"), ("Failed run", "Costs nothing")],
                   ["You see the price before anything starts.", "And a failed run costs nothing."]))
    ai = next(i for i, x in enumerate(scenes) if x["type"] == "approve"); scenes.insert(ai, extra)
    c = scenes[-1]; c["sentences"] = ["One hundred free credits. No card needed."] + c["sentences"] + ["We make the video. You press publish."]
    return scenes


def main():
    os.makedirs(os.path.join(ROOT, "queue"), exist_ok=True)
    pp = os.path.join(ROOT, "queue", "plan.json")
    old = {e["id"]: e for e in json.load(open(pp))["episodes"]} if os.path.exists(pp) else {}
    plan = []
    for n, (slug, title, xtext, scenes, facts, prompts) in enumerate(EPS):
        eid = f"ep{n + 6:03d}-{slug}"; pal = PALS[n % len(PALS)]
        assert len(xtext) < 280 and "nightshift-ai.studio" in xtext and "https://" not in xtext, eid
        scenes = pad(slug, scenes)
        facts = facts + [(HOME, "You see the price first"), (HOME, "A failed run costs nothing"), (HOME, "Need just one piece? The Studio makes it."),
                         (STUDIO, "Editing and exporting use no credits"), (HOME, "We make the video.")] + PRIVATE
        hook_i, appr_i = 0, next(i for i, s in enumerate(scenes) if s["type"] == "approve")
        clips = []
        for k, (si, pr) in enumerate([(hook_i, prompts[0]), (appr_i, prompts[1])]):
            key = f"{eid}-{k}"; prev = {c["key"]: c for c in old.get(eid, {}).get("clips", [])}.get(key, {})
            clips.append(dict(key=key, scene=si, prompt=pr + STYLE, status=prev.get("status", "todo"), job_id=prev.get("job_id"), url=prev.get("url")))
            scenes[si]["broll"] = f"broll/{key}.mp4"
        ep = {"id": eid, "palette": pal, "title": title, "scenes": scenes}
        json.dump(ep, open(os.path.join(ROOT, "episodes", eid + ".json"), "w"), indent=1)
        o = old.get(eid, {})
        plan.append(dict(id=eid, day=n + 1, title=title, palette=pal, x_text=xtext, facts=[{"page": p, "quote": q} for p, q in facts],
                         clips=clips, render=o.get("render", "todo"), asset=o.get("asset"), published=o.get("published")))
    json.dump({"note": "30-day queue. See RUNBOOK.md 'Queue'. status: todo -> submitted -> done; render: todo -> stashed", "episodes": plan},
              open(pp, "w"), indent=1)
    print("wrote", len(plan), "episodes")


if __name__ == "__main__":
    main()
